namespace AccessControl;

public sealed class AccessDecisionEngine
{
    public AccessDecision Decide(Principal? principal, Resource? resource, AccessRequest? request, IDelegationRegister delegations)
    {
        if (principal is null || resource is null || request is null)
            return new AccessDecision(false, "missing-context", true);

        var validationDecision = ValidatePrincipalAndResource(principal, resource)
            ?? ValidateRequestConstraints(principal, resource, request);
        if (validationDecision is not null)
            return validationDecision;

        var authorization = GetAuthorizationContext(principal, resource, request, delegations);
        return EvaluateRequest(resource, request, authorization);
    }

    private static AccessDecision? ValidatePrincipalAndResource(Principal principal, Resource resource)
    {
        if (string.IsNullOrWhiteSpace(principal.Id) || string.IsNullOrWhiteSpace(resource.Id))
            return new AccessDecision(false, "invalid-identity", true);
        if (principal.Suspended)
            return new AccessDecision(false, "principal-suspended", true);
        if (!string.Equals(principal.TenantId, resource.TenantId, StringComparison.Ordinal))
            return new AccessDecision(false, "tenant-mismatch", true);

        return null;
    }

    private static AccessDecision? ValidateRequestConstraints(
        Principal principal,
        Resource resource,
        AccessRequest request)
    {
        if (resource.Locked && request.Action != "read")
            return new AccessDecision(false, "resource-locked", true);
        if (request.MinuteOfDay is < 0 or > 1439)
            return new AccessDecision(false, "invalid-time", true);
        if (principal.FailedChallenges >= 3 && !request.StrongAuthentication)
            return new AccessDecision(false, "challenge-required", true);

        return null;
    }

    private static AuthorizationContext GetAuthorizationContext(
        Principal principal,
        Resource resource,
        AccessRequest request,
        IDelegationRegister delegations)
    {
        var administrator = principal.Roles.Contains("administrator");
        var operatorRole = principal.Roles.Contains("operator");
        var auditor = principal.Roles.Contains("auditor");
        var owner = principal.Id == resource.OwnerId;
        var delegated = delegations.HasDelegation(principal.Id, resource.Id, request.Action);

        return new AuthorizationContext(administrator, operatorRole, auditor, owner, delegated);
    }

    private static AccessDecision EvaluateRequest(
        Resource resource,
        AccessRequest request,
        AuthorizationContext authorization)
    {
        var breakGlassDecision = EvaluateBreakGlass(request, authorization);
        if (breakGlassDecision is not null)
            return breakGlassDecision;

        var classificationDecision = EvaluateClassification(resource, request);
        if (classificationDecision is not null)
            return classificationDecision;

        return EvaluateAction(resource, request, authorization);
    }

    private static AccessDecision? EvaluateBreakGlass(
        AccessRequest request,
        AuthorizationContext authorization)
    {
        if (!request.BreakGlass)
            return null;
        if (!authorization.Administrator || !request.StrongAuthentication)
            return new AccessDecision(false, "invalid-break-glass", true);

        return new AccessDecision(true, "break-glass", true);
    }

    private static AccessDecision? EvaluateClassification(Resource resource, AccessRequest request)
    {
        if (resource.Classification == "restricted" && !request.StrongAuthentication)
            return new AccessDecision(false, "strong-authentication-required", true);
        if (resource.Classification == "restricted" && request.NetworkZone != "trusted")
            return new AccessDecision(false, "trusted-network-required", true);

        return null;
    }

    private static AccessDecision EvaluateAction(
        Resource resource,
        AccessRequest request,
        AuthorizationContext authorization)
    {
        return request.Action switch
        {
            "delete" => EvaluateDelete(resource, request, authorization),
            "write" => EvaluateWrite(resource, request, authorization),
            "read" => EvaluateRead(resource, request, authorization),
            _ => new AccessDecision(false, "unknown-action", true)
        };
    }

    private static AccessDecision EvaluateDelete(
        Resource resource,
        AccessRequest request,
        AuthorizationContext authorization)
    {
        if (!authorization.Administrator)
            return new AccessDecision(false, "administrator-required", true);

        return CreateAllowedDecision(resource, request, authorization.Delegated);
    }

    private static AccessDecision EvaluateWrite(
        Resource resource,
        AccessRequest request,
        AuthorizationContext authorization)
    {
        if (!(authorization.Administrator || authorization.Operator || authorization.Owner || authorization.Delegated))
            return new AccessDecision(false, "write-not-authorised", true);

        return CreateAllowedDecision(resource, request, authorization.Delegated);
    }

    private static AccessDecision EvaluateRead(
        Resource resource,
        AccessRequest request,
        AuthorizationContext authorization)
    {
        if (!(authorization.Administrator || authorization.Operator || authorization.Auditor || authorization.Owner || authorization.Delegated))
            return new AccessDecision(false, "read-not-authorised", false);

        return CreateAllowedDecision(resource, request, authorization.Delegated);
    }

    private static AccessDecision CreateAllowedDecision(Resource resource, AccessRequest request, bool delegated)
    {
        var outsideBusinessHours = request.MinuteOfDay < 480 || request.MinuteOfDay > 1080;
        return new AccessDecision(
            true,
            delegated ? "delegated" : "role-or-ownership",
            outsideBusinessHours || resource.Classification == "restricted");
    }

    private readonly record struct AuthorizationContext(
        bool Administrator,
        bool Operator,
        bool Auditor,
        bool Owner,
        bool Delegated);
}
